+const normalAnswer = "재개 정상 확인";
+const interruptPrompt = "도구를 사용하거나 파일을 만들지 마세요. 숫자와 짧은 한글 문장을 400줄 이상 작성하세요. 1번부터 즉시 시작하세요.";
